-- TASK-220. V2 network theory + 300 exam-style answer-choice items.
-- Source: Kompyuter_tarmoqlari_300_savol_V2.json + 2026 specification.
-- Safe/append-only: preserves M12 legacy lessons, questions, attempts and published revisions.
-- AI content stays DRAFT (theory) / REVIEW (questions) pending human expert approval.
-- Original Y2/Y3 answer-combination samples are explicitly modeled as Y1
-- until native matching/order content is independently reauthored.
BEGIN;
DO $task220$
DECLARE
  v_module uuid;
  v_subject uuid;
  x jsonb;
  q jsonb;
  c uuid;
  qid uuid;
  lid uuid;
  oid uuid;
  chosen uuid;
  k integer;
  source text;
  actual_count integer;
  visual_md text;
BEGIN
  SELECT id INTO STRICT v_module FROM public.modules WHERE code='M12';
  SELECT id INTO STRICT v_subject FROM public.subjects WHERE code='informatika';
  FOR x IN SELECT value FROM jsonb_array_elements($theory$[{"ch":1,"title":"Kompyuter tarmog'i va uning turlari","body":"# Kompyuter tarmog'i va uning turlari\n\n**Maqsad**\n\nTarmoqni, uning tarkibiy qismlarini va hududiy turlarini aniqlash; tarmoq tanlash vaziyatlarini izohlash.\n\n## Ta'rif, vazifa va resurslar\n\n**Kompyuter tarmog'i** — kompyuterlar va boshqa raqamli qurilmalarni aloqa kanallari hamda tegishli apparat-dasturiy vositalar orqali bog'lab, ma'lumot almashish va resurslardan birgalikda foydalanishni ta'minlovchi tizim. **Tugun** (node) — tarmoqqa ulangan element; **xost** (host) odatda manzillanadigan yakuniy qurilma; **server** — boshqa ishtirokchilarga xizmat ko'rsatuvchi tizim. Bitta jismoniy server bir necha xizmatni, bitta xizmat esa bir necha serverda bajarilishi mumkin.\n\nTarmoqqa ulanishning maqsadlari: fayl almashish, markazlashgan saqlash, umumiy printer, internetga chiqish, elektron muloqot, zaxiralash, masofaviy ishlash. Cheklovlari: dastlabki xarajat, boshqaruv va xavfsizlik talablari, markaziy nuqtaga qaramlik, tarmoqdagi nosozlik ta'siri.\n\n**Eslatma: Atamalarni ajrating**\n\nInternet — dunyo miqyosidagi o'zaro bog'langan IP tarmoqlari; lokal tarmoq esa internetga ulanmasdan ham ishlashi mumkin. Wi-Fi — simsiz lokal tarmoqqa ulanish texnologiyasi, internetning sinonimi emas.\n\n## Tarmoqning tarkibi\n\nTarkib | Vazifa\n\nYakuniy qurilma | Noutbuk, telefon, printer, server; ma'lumot yaratadi, oladi yoki xizmat ko'rsatadi.\n\nTarmoq interfeysi (NIC) | Qurilmani Ethernet yoki Wi-Fi tarmog'iga ulaydi; odatda kanal darajasida MAC manzili mavjud.\n\nUzatish muhiti | Mis kabel, optik tola yoki radioto'lqin; signal shu muhit orqali tarqaladi.\n\nOraliq qurilma | Switch, router, access point, modem va boshqalar; uzatish hamda yo'naltirishga yordam beradi.\n\nTarmoq dasturi/protokol | Qurilmalar o'zaro qanday muloqot qilishini belgilaydi.\n\n## Hududiy turlar\n\nTur | Qamrov va mazmun | Misol\n\nPAN/WPAN | Shaxsning yaqin atrofidagi qurilmalar; ko'pincha Bluetooth. | Telefon va quloqchin.\n\nHAN | Uy ichidagi tarmoq. | Uy routeriga ulangan qurilmalar.\n\nLAN/WLAN | Xona, bino, kampusning mahalliy segmenti; WLAN simsiz LAN. | Maktab kompyuter xonasi.\n\nMAN | Shahar miqyosidagi bog'lanish. | Shahardagi bir necha filial.\n\nWAN | Katta geografik masofadagi tarmoqlarni bog'lash. | Turli viloyatlardagi filiallar.\n\nInternet | Mustaqil IP tarmoqlarining global birlashmasi. | Umumjahon internet.\n\n**Diqqat: Shartga qarab javob**\n\nTarmoq turi faqat kabelning mavjudligi bilan belgilanmaydi. *WLAN* ham lokal tarmoq; *WAN* doimo simsiz degani emas. Bir tashkilotning bir shahardagi turli manzillari LAN, MAN yoki WAN arxitekturasi yordamida bog'lanishi mumkin: testdagi aniq qamrov va aloqa usulini tekshiring.\n\n## Internet, intranet va extranet chegaralari\n\n**Internet** --- turli tashkilotlarga qarashli IP tarmoqlarining global birlashmasi. **Intranet** --- tashkilot ichidagi xodimlar uchun mo'ljallangan, ko'pincha veb-texnologiyalardan foydalanuvchi cheklangan resurslar muhiti. **Extranet** --- tashkilotning ayrim ichki resurslariga ruxsat etilgan tashqi hamkorlarni nazorat bilan kiritish shakli. *Intranet* faqat Internetdan uzilgan alohida kabel bo'lishi shart emas: tashkilot VPN kabi himoyalangan kanal orqali masofadagi xodimga intranet kirishini berishi mumkin.\n\nTushuncha | Asosiy auditoriya | Vaziyat\n\nInternet | Umumiy ochiq global infratuzilma | Ommaviy veb-sayt\n\nIntranet | Ichki ruxsatli xodimlar | Maktabning ichki hujjat portali\n\nExtranet | Ruxsatli tashqi hamkor | Ta'minotchiga cheklangan buyurtma portali\n\n**Ishlangan misol: Bir bino, uch xizmat**\n\nO'quvchi ommaviy ta'lim portalini ochadi (Internet), o'qituvchi maxsus login bilan maktabning ichki jadvaliga kiradi (intranet), tashqi ta'minotchi buyurtmaning faqat o'ziga tegishli qismini ko'radi (extranet). Uchchala xizmat ham IP/veb protokollaridan foydalanishi mumkin; farq --- ruxsat va auditoriya.\n\n*Manba: M11, darslikning 136--138-betlari, 19--20-darslar (intranet); extranet --- mavzuga oid qo'shimcha aniqlashtirish.*\n\n## Simli va simsiz tarmoq\n\nSimli Ethernetda odatiy muhit — o'ralgan juftlik (UTP/STP) yoki optik tola. Simsiz WLAN radiokanaldan foydalanadi. Simli ulanish barqarorlik va boshqariladigan fizik kirishni ta'minlashi mumkin; Wi-Fi qurilma harakatchanligiga qulay. Haqiqiy unumdorlik signal, masofa, xalaqit, foydalanuvchilar soni va uskunaga bog'liq.\n\n**Ishlangan misol: Vaziyat**\n\nMaktab binosidagi 20 ta kompyuter bitta printerni ulashib ishlatadi. Internet uzilib qoldi, lekin lokal switch va printer ishlayapti. Lokal printer ishlashda davom etishi mumkin: *LAN* va *internet* bir xil emas.\n\n*Manba: M11, 129--139-betlar (19--20-darslar); C11, tarmoqlar bo'limi.*\n\n**Xulosa:** PAN — shaxsiy; LAN — mahalliy; MAN — shahar; WAN — uzoq masofa. Tarmoqdan foydalanish internetga chiqish bilangina cheklanmaydi.\n\n*V2 manba: 2026 spetsifikatsiya, 11-sinf va qo‘shimcha Cambridge darsliklari; ekspert ko‘rigi kutilmoqda.*"},{"ch":2,"title":"Tarmoq qurilmalari va uzatish muhiti","body":"# Tarmoq qurilmalari va uzatish muhiti\n\n**Maqsad**\n\nHar bir qurilmani unga mos vazifa va darajada farqlash; tarmoq vaziyatida to'g'ri qurilmani tanlash.\n\n## Asosiy qurilmalar\n\nQurilma | Asosiy vazifa | Nozik farq\n\n**NIC** | Kompyuterga tarmoq interfeysi taqdim etadi. | IP va MAC aynan bir narsa emas.\n\n**Hub** | Kelgan bit/signalni boshqa portlarga qayta uzatadi. | Manzil bo'yicha tanlab yubormaydi.\n\n**Switch** | Ethernet freymlarini MAC jadvallari yordamida kerakli portga uzatadi. | Oddiy Layer 2 switch — marshrutizator emas.\n\n**Router** | IP paketlarni turli IP tarmoqlari orasida yo'naltiradi. | Default gateway ko'pincha router interfeysi.\n\n**Access point** | Simsiz klientlarni LANga ulaydi. | AP har doim router bo'lishi shart emas.\n\n**Modem** | Provayderning kirish kanaliga xos signal/interfeysni moslashtiradi. | Modem, router va Wi-Fi AP turli vazifa.\n\n**Repeater** | Signalni regeneratsiya/uzoqroq uzatishga yordam beradi. | Paketlarni IP bo'yicha marshrutlamaydi.\n\n**Bridge** | Ikki kanal segmentini MAC darajasida bog'laydi. | Zamonaviy switch ko'p portli ko'prikka yaqin.\n\n**Firewall** | Belgilangan qoidalar bo'yicha trafikni nazorat/filtr qiladi. | Alohida qurilma yoki dastur bo'lishi mumkin.\n\n**Server** | Fayl, veb, DNS, DHCP kabi xizmatlarni beradi. | Qurilma roli mantiqiy; server oddiy kompyuter ham bo'lishi mumkin.\n\n## Server turlari va tarmoqdagi dasturiy komponentlar\n\n11-sinf darsligida tarmoqning **texnik komponentlari** sifatida abonent qurilmalari, aloqa kanallari, adapter, kommutator, ko'prik va router; **dasturiy komponentlari** sifatida tarmoq operatsion tizimlari va ulanishni ta'minlovchi protokol-xizmatlar ajratilgan. Misollar: Windows Server/Linux kabi tizimlar, tarmoq mijozi, fayllarni ulashish va masofaviy kirish xizmatlari. Tarmoq operatsion tizimi apparat qurilma emas.\n\nServer turi | Qanday xizmat ko'rsatadi?\n\nFayl-server | Umumiy fayllarni saqlash va ruxsat bilan ulashish\n\nPrint-server | Chop etish so'rovlarini navbatlash va printerdan umumiy foydalanish\n\nVeb-server | HTTP(S) so'rovlariga veb-resurs yuborish\n\nPochta serveri | Xatni uzatish, qabul qilish yoki qutini saqlash\n\nMa'lumotlar bazasi serveri | So'rov asosida markazlashgan ma'lumotga kirish\n\n**Diqqat: Server tushunchasini yoddan chiqarmang**\n\n*Server* ko'p hollarda xizmatni bajaruvchi dastur yoki shu dasturni ishlatayotgan kompyuter degani. ``Har bir xizmat uchun alohida jismoniy kompyuter shart'' va ``har bir server internetdagi ommaga ochiq'' kabi hukmlar noto'g'ri. Mijoz-server modeli topologiya bilan aynan bir xil emas.\n\n*Manba: M11, 140--145-betlar (21-dars), 160--163-betlar (tarmoq dasturiy ta'minoti); C8, kompyuter tarmog'i moduli, PDF 91--113-betlar.*\n\n## Kadr (frame) va paket (packet)\n\nEthernet kommutatori odatda freymdagi **MAC** manziliga, router esa paketdagi **IP** manziliga qarab qaror qabul qiladi. IP manzili tarmoqqa qarab o'zgarishi mumkin; MAC interfeysning kanal darajasidagi identifikatoridir. Ushbu farq testda ko'p chalg'itadi.\n\n**Sxema:** tarmoq elementlari va ularning ulanishi (asl PDFda diagramma mavjud).\n\n## Aloqa vositalari\n\nMuhit | Amaliy xususiyat\n\nO'ralgan juft kabel | Ethernet LAN; RJ-45 ulagich ko'p uchraydi. UTP va STP ekranlanganlik bilan farqlanadi.\n\nOptik tolali kabel | Ma'lumotni yorug'lik impulslarida uzatadi; elektromagnit shovqinga chidamli, uzoq masofa uchun qulay.\n\nKoaksial kabel | Tarixiy LAN va ayrim provayder aloqa kanallarida qo'llanadi.\n\nRadio (Wi-Fi/Bluetooth) | Simsiz va qulay; radiochastota, to'siq va xalaqitga sezgir.\n\n**Ishlangan misol: Uch xil nosozlik**\n\n1) Bir lokal xonada yangi kompyuter uchun bo'sh Ethernet port kerak: **switch**. 2) `192.168.1.0/24` dan `192.168.2.0/24` ga trafik: **router**. 3) Simsiz telefonlarni mavjud simli LANga ulash: **access point**.\n\n**Diqqat: Bir qutida bir necha vazifa**\n\nUy uchun sotiladigan ``Wi-Fi router'' odatda router + switch + access point + ba'zan modem funksiyalarini o'z ichiga oladi. Qurilmaning savdo nomidan emas, savolda talab qilingan *funksiyadan* kelib chiqing.\n\n*Manba: M11, 156--166-betlar (24--25-darslar); C11, 13-bob, tarmoq komponentlari.*\n\n**Xulosa:** Switch — MAC bo'yicha LAN ichida; router — IP bo'yicha tarmoqlar orasida; AP — simsiz kirish; modem — kanalga moslash.\n\n## Aloqa kanallarining kengaytirilgan tasnifi\n\n**Simli muhitlar**: o'ralgan juftlik UTP/STP (mis), koaksial kabel (mis), optik tola (yorug'lik). **Simsiz muhitlar**: qisqa masofali Bluetooth, Wi-Fi (WLAN), uyali mobil aloqa, radiorele/mikroto'lqin, infraqizil aloqa va sun'iy yo'ldosh kanali. Tarmoq turi (LAN/WAN) bilan signal muhiti (simli/simsiz) --- ikki mustaqil mezon.\n\nMuhit | Afzallik | Cheklov yoki vaziyat\n\nUTP/STP | Keng tarqalgan LAN ulanishi | Misda xalaqit va masofa hisobga olinadi; STP ekranli\n\nOptik tola | Elektromagnit xalaqitga chidamli; katta hajm | Optik transiver va montaj talab qiladi\n\nKoaksial | Ekranli mis kabel | Kabel TV va ayrim eski tarmoqlarda\n\nWi-Fi | Qulay mobil ulanish | Radio shovqin, devorlar, xavfsizlik sozlamalari\n\nUyali aloqa | Operator qamrovida mobillik | Qamrov va tarifga bog'liq\n\nSun'iy yo'ldosh | O'zaro juda uzoq/yetib borish qiyin hududlar | Kechikish va atmosfera ta'siri turlicha\n\n**Ishlangan misol: Kanal tanlash**\n\nMaktab binolari orasida elektromagnit shovqin kuchli va kabel masofasi uzun. Optik tola mos bo'lishi mumkin. Harakatdagi planshetlar uchun AP orqali Wi-Fi qulay. Uzoq qishloq hududida yer usti magistrali yo'q bo'lsa, sun'iy yo'ldosh yoki mobil operator aloqa varianti baholanadi; har birini narx, qamrov, uzilish xavfi va tezlik bilan solishtiring.\n\n*Manba: M11, 146--155-betlar (22--23-dars), simli/simsiz aloqa texnologiyalari; C8, PDF 91--113-betlar.*\n\n*V2 manba: 2026 spetsifikatsiya, 11-sinf va qo‘shimcha Cambridge darsliklari; ekspert ko‘rigi kutilmoqda.*"},{"ch":3,"title":"Tarmoq arxitekturasi va topologiyasi","body":"# Tarmoq arxitekturasi va topologiyasi\n\n**Maqsad**\n\nMijoz-server va P2P modelini hamda fizik/mantiqiy topologiyani farqlash; nosozlik nuqtalarini tahlil qilish.\n\n## Mijoz-server va teng huquqli model\n\n**Client--server**: mijoz (client) so'rov yuboradi, server javob beradi yoki resursni taqdim etadi. Markaziy autentifikatsiya, yagona zaxira va boshqaruv uchun qulay; server yoki ulanishdagi nosozlik xizmatni cheklashi mumkin. **Peer-to-peer (P2P)**: qurilmalar bir-biriga teng darajada bevosita xizmat ko'rsatishi mumkin. Kichik tarmoqlarda sodda; markazlashgan ruxsat va boshqaruv murakkabroq bo'lishi mumkin.\n\nMezon | Client--server | P2P\n\nResurs | Ko'pincha markazlashgan | Ishtirokchilar o'rtasida\n\nBoshqaruv | Yagona siyosatni joriy etish qulay | Har bir tugunda alohida bo'lishi mumkin\n\nMisol | Maktab domenida fayl serveri | Ikki kompyuterning fayl almashishi\n\n## Topologiya: ulanish sxemasi\n\n**Fizik topologiya** — qurilmalar va aloqa kanallarining jismoniy joylashuvi; **mantiqiy topologiya** — ma'lumot oqimi va aloqa tartibi. Turli mantiqiy ishlashlar bir xil fizik chizmada amalga oshishi mumkin.\n\nTopologiya | Asosiy belgisi | Nosozlikdagi xatar\n\nShina (bus) | Umumiy magistral kabel | Magistral uzilsa ko'p tugun ta'sirlanadi.\n\nHalqa (ring) | Tugunlar yopiq zanjir | Oddiy halqada bir uzilish muammoli; zaxira halqa bo'lishi mumkin.\n\nYulduz (star) | Har tugun markaziy switchga ulanadi | Markaziy qurilma yagona xato nuqtasi.\n\nTo'rli (mesh) | Tugunlar orasida bir nechta yo'l | Yuqori chidamlilik, ammo ko'p aloqa talab etishi mumkin.\n\nDaraxt (tree) | Ierarxik yulduzlar | Yuqori bosqich qurilmasi quyi qismlarga ta'sir qilishi mumkin.\n\nGibrid | Bir necha topologiya aralashmasi | Xatar tanlangan segmentlar strukturasiga bog'liq.\n\n**Sxema:** tarmoq elementlari va ularning ulanishi (asl PDFda diagramma mavjud).\n\n## Sxemani o'qish: fizik va xizmat arxitekturasi\n\n**Sxema:** tarmoq elementlari va ularning ulanishi (asl PDFda diagramma mavjud).\n\nRasmda barcha chekka tugunlar markaziy switchga ulanadi: **fizik topologiya --- yulduz**. Server markazda chizilmagani sababli uning xizmat roli kamaymaydi: **mijoz/server** arxitekturasi alohida masala. Router boshqa IP tarmoqqa o'tish uchun kerak bo'lishi mumkin, lekin faqat bitta LAN printerini ulashish uchun doimo shart emas.\n\n*Manba: M11, 140--145, 167--171-betlar; sxema --- sintez qilingan mashq.*\n\n## To'liq mesh uchun bog'lanishlar soni\n\nAgar $n$ ta tugunning *har bir jufti* alohida ikki tomonlama aloqa bilan bog'lansa, qirralar soni\n\\[E=\\frac{n(n-1)}{2}.\\]\n\n**Ishlangan misol: Hisoblash**\n\n6 ta tugunli to'liq meshda $E=6\\cdot5/2=15$ ta aloqa bor. Bu formula shina, yulduz yoki qisman mesh uchun bevosita qo'llanmaydi.\n\n**Diqqat: Halqa haqida mutlaq hukm qilmang**\n\nOddiy yagona halqada bir uzilish aloqa to'xtashiga olib kelishi mumkin; lekin zaxiralangan halqa protokollarida boshqa yo'l bor. Test ``oddiy halqa'' deyaptimi yoki ortiqcha yo'l mavjudligini ko'rsatyaptimi — aniqlang.\n\n*Manba: M11, 140--145 va 167--171-betlar (21 va 26-darslar); C11, tarmoq arxitekturasi.*\n\n**Xulosa:** Mijoz-server — rollar; yulduz/halqa/shina — ulanish shakli. Bu ikki tasnifni bir-biriga almashtirmang.\n\n*V2 manba: 2026 spetsifikatsiya, 11-sinf va qo‘shimcha Cambridge darsliklari; ekspert ko‘rigi kutilmoqda.*"},{"ch":4,"title":"Tarmoqlarning ishlash prinsipi va protokollar","body":"# Tarmoqlarning ishlash prinsipi va protokollar\n\n**Maqsad**\n\nUzatish yo'lini, qatlamlarni va TCP/IP oilasining vazifalarini ajratish; muammolarni qatlamga bog'lash.\n\n## Paketli uzatish\n\nMa'lumot kichik birliklarga ajratilib, sarlavhalar bilan uzatilishi mumkin. **IP paketi** tarmoqlar o'rtasida yetkaziladi; **Ethernet freymi** lokal kanal bo'ylab uzatiladi; **TCP segmenti** transport darajasidagi ma'lumotni tashiydi. Turli qatlamlarda ``paket'' so'zi umumiy ma'noda ishlatilsa ham, attestatsiyada qaysi sarlavha qaysi darajaga tegishli ekanini ajrating.\n\n## Soddalashtirilgan TCP/IP modeli\n\nQatlam | Vazifa | Misollar\n\nIlova | Foydalanuvchi xizmatlari va so'rovlar | HTTP(S), DNS, SMTP, IMAP, DHCP\n\nTransport | Dasturlar o'rtasida uzatish | TCP, UDP, portlar\n\nInternet | Tarmoqlararo manzillash va yo'naltirish | IPv4, IPv6, ICMP\n\nKanal va fizik | Mahalliy kadr va signal uzatish | Ethernet, Wi-Fi, MAC, optik kabel\n\n## TCP va UDP farqi\n\n**TCP** ulanishni o'rnatadi, tartib va yo'qolgan ma'lumotlarni qayta uzatishni boshqaradi; **UDP** bog'lanishsiz datagrammalarni yuboradi va TCPdagi kafolatlarni o'zida bermaydi. UDP ishlatilgan xizmat ham ilova darajasida nazorat mexanizmlariga ega bo'lishi mumkin. ``UDP har doim tez'' yoki ``TCP har doim sekin'' — mutlaq to'g'ri emas.\n\n## IP, MAC, port va DNS\n\nAtama | Asosiy savolga javob\n\nMAC | Shu lokal kanal ichida qaysi interfeys?\n\nIP | Qaysi tarmoqdagi qaysi interfeys?\n\nPort | Qaysi xizmat/dastur muloqotining oxirgi nuqtasi?\n\nDNS | Domen nomiga mos manzilni qanday topamiz?\n\n## Tarmoqdan tashqariga uzatish yo'li\n\n- Kompyuter maska asosida qabul qiluvchining manzili o'z subnetidami-yo'qmi tekshiradi.\n\n- Bir subnetda bo'lsa, lokal aloqa uchun kerakli MAC aniqlanadi (IPv4da ARP).\n\n- Boshqa subnetda bo'lsa, paket **default gateway**ga yuboriladi; IP manzil qabul qiluvchining o'ziniki bo'lib qoladi, lokal Ethernet freymi esa keyingi uzatish uchun o'zgaradi.\n\n- Router yo'naltirish jadvali bo'yicha navbatdagi manzilni tanlaydi; bu jarayon paket manzilga yetguncha davom etadi.\n\n**Ishlangan misol: DNS so'rovi va veb sahifa**\n\nFoydalanuvchi `example.org` ni ochadi: (1) kerak bo'lsa DNS orqali IPni aniqlaydi; (2) server bilan bog'lanishni o'rnatadi; (3) HTTP(S) so'rovini yuboradi; (4) server javobini oladi. Brauzerning o'zi qidiruv tizimi emas, DNS esa veb-sahifalarning mazmunini indekslamaydi.\n\n## O'tkazuvchanlik, kechikish va uzatish vaqti\n\n**Bandwidth** — kanalning nazariy o'tkazish qobiliyati, **throughput** — amalda uzatilgan foydali hajm tezligi, **latency** — kechikish, **packet loss** — yo'qolgan paketlar ulushi. Soddalashtirilgan hisob:\n\\[t=\\frac{D}{v},\\qquad 1\\ \\mathrm{B}=8\\ \\mathrm{bit}.\\]\n\n**Ishlangan misol: Hisoblash**\n\n24 MB fayl (MB = $10^6$ bayt) 12 Mbit/s samarali uzatish tezligida yuborilsa: $24\\cdot8/12=16$ s. Protokol xarajatlari yoki qo'shimcha kechikish berilmaganligi uchun bu ideal soddalashtirilgan qiymat.\n\n*Manba: M11, 146--155, 172--179-betlar; C11, tarmoq va axborot uzatish mavzulari.*\n\n**Xulosa:** MAC mahalliy kadr, IP tarmoqlararo paket, TCP/UDP transport, HTTP(S)/DNS ilova qatlamiga tegishli.\n\n*V2 manba: 2026 spetsifikatsiya, 11-sinf va qo‘shimcha Cambridge darsliklari; ekspert ko‘rigi kutilmoqda.*"},{"ch":5,"title":"IPv4 manzillash va subnet maskasi","body":"# IPv4 manzillash va subnet maskasi\n\n**Maqsad**\n\nIPv4 tuzilishi, tarmoq va host qismi, CIDR va dotted-decimal maskalarni aniqlash; maxsus manzillarni farqlash.\n\n## IPv4 32 bitdan iborat\n\n**IPv4** — 32 bitli manzil: 4 ta 8 bitli oktet, nuqtalar bilan ajratiladi. Har bir oktet $0$ dan $255$ gacha. Masalan, `192.168.10.34` — sintaktik jihatdan to'g'ri IPv4. `192.168.10.256` noto'g'ri, chunki 256 bitta oktetga sig'maydi. IPv4 manzil — interfeysning mantiqiy tarmoq manzili; butun internetda hamisha noyob bo'lishi shart emas (xususiy IP bir nechta mustaqil tarmoqlarda takrorlanishi mumkin).\n\\[192=128+64=11000000_2,\\qquad 168=10101000_2.\\]\n\n## Subnet maskasi va prefiks\n\n**Subnet maskasi** — tarmoq qismini 1 bitlar, host qismini 0 bitlar yordamida belgilaydigan 32 bitli niqob. **CIDR /$p$** — chapdan ketma-ket joylashgan $p$ ta bir. Standart uzluksiz maskada avval hamma 1 bitlar, keyin 0 bitlar keladi.\n\nCIDR | Maskasi | Manzil soni\n\n/8 | 255.0.0.0 | $2^{24}$\n\n/16 | 255.255.0.0 | $2^{16}$\n\n/20 | 255.255.240.0 | $2^{12}$\n\n/24 | 255.255.255.0 | $2^8=256$\n\n/25 | 255.255.255.128 | $2^7=128$\n\n/26 | 255.255.255.192 | $2^6=64$\n\n/27 | 255.255.255.224 | $2^5=32$\n\n/28 | 255.255.255.240 | $2^4=16$\n\n/29 | 255.255.255.248 | $2^3=8$\n\n/30 | 255.255.255.252 | $2^2=4$\n\n**Diqqat: Maskada mumkin bo'lgan qiymatlar**\n\nOddiy uzluksiz maskaning bitta chegaraviy okteti faqat $0,128,192,224,240,248,252,254,255$ qiymatlaridan biri bo'lishi mumkin. Masalan `255.255.255.192` (/26) to'g'ri; `255.255.255.160` uzluksiz maska emas ($10100000_2$).\n\n## IPv4 manzillarning vazifaviy turlari\n\nDiapazon | Vazifa\n\n10.0.0.0/8 | RFC 1918 xususiy IPv4\n\n172.16.0.0/12 | RFC 1918 xususiy IPv4: 172.16--172.31\n\n192.168.0.0/16 | RFC 1918 xususiy IPv4\n\n127.0.0.0/8 | Loopback: shu qurilmaga qaytish, masalan 127.0.0.1\n\n169.254.0.0/16 | IPv4 link-local (avtomatik mahalliy manzil)\n\n0.0.0.0 | Maxsus unspecified / marshrut kontekstida default-route yozuvi\n\n255.255.255.255 | Cheklangan broadcast\n\n224.0.0.0/4 | Multicast\n\n198.51.100.0/24 | Hujjat va misollar uchun rezervlangan diapazon\n\n**Eslatma: RFC 1918ni esda saqlang**\n\nXususiy uchta blok: `10/8`, `172.16/12`, `192.168/16`. `172.32.1.1` xususiy emas; `172.31.250.2` xususiydir. Global Internetdan bevosita yo'naltirilmaydigan barcha manzillarni ``xususiy'' deb umumlashtirmang.\n\n## Sinfli tarixiy manzillash va CIDR\n\nTarixiy **classful** tasnif: A (birinchi oktet 1--126, odatiy /8), B (128--191, odatiy /16), C (192--223, odatiy /24); D (224--239, multicast), E (240--255, tajriba/maxsus). 127 loopback uchun, 0 esa maxsus. Zamonaviy tarmoqlar **CIDR** asosida ishlaydi: masalan `10.5.9.1/27` A sinfdagi boshlang'ich oktetga ega bo'lsa-da, uning aktual prefiksi */27*, /8 emas.\n\n**Ishlangan misol: Manzilni ikkilikka o'tkazish**\n\n`192.168.10.34/27`:\n\n\\text{oxirgi oktet} | : 34=00100010_2,\n\n\\text{maska oxirgi oktet} | : 224=11100000_2.\n\nDemak 5 ta host biti bor. Tarmoq va broadcastni keyingi bobda hisoblaymiz.\n\n*Manba: M11, 172--179-betlar, 27--28-dars; CIDR va rezerv manzillar — ilmiy-texnik aniqlashtirish.*\n\n**Xulosa:** IPv4 — 32 bit; /$p$ — tarmoq bitlari; $32-p$ — host bitlari. RFC~1918 xususiy bloklarni loopback va link-localdan farqlang.\n\n*V2 manba: 2026 spetsifikatsiya, 11-sinf va qo‘shimcha Cambridge darsliklari; ekspert ko‘rigi kutilmoqda.*"},{"ch":6,"title":"Network, broadcast va host diapazonini hisoblash","body":"# Network, broadcast va host diapazonini hisoblash\n\n**Maqsad**\n\nIPv4 subnetning network, broadcast, birinchi/oxirgi foydalaniladigan hostini va hostlar sonini mustaqil topish.\n\n## Formal hisoblash qoidalari\n\nIP manzil $A$, niqob $M$ bo'lsa,\n\\[\\boxed{N=A\\ \\mathrm{AND}\\ M},\\qquad\\boxed{B=N\\ \\mathrm{OR}\\ (\\mathrm{NOT}\\ M)}.\\]\nBu yerda $N$ — **network address**, $B$ — **broadcast address**. AND: $1\\land 1=1$, boshqa hollarda 0; OR: ikkalasi 0 bo'lsagina 0. *NOT* 32 bit doirasida olinadi. Oddiy IPv4 subnetda $h=32-p$ bo'lsa, jami manzillar $2^h$, /0--/30 uchun odatiy usable-host soni $2^h-2$. Ikki manzil tarmoq va broadcastga ajratiladi.\n\n**Diqqat: /31 va /32 alohida istisno**\n\n/31 odatda point-to-point bog'lanishlarda maxsus qoida bilan har ikki manzildan foydalanishga ruxsat berishi mumkin; /32 bitta aniq manzilni ifodalaydi. Shuning uchun $2^h-2$ formulani ularga ko'r-ko'rona qo'llamang. Hisoblash mashqlarida /0--/30 yoki istisno sharti aniq beriladi.\n\n## Tezkor blok usuli\n\nQisman to'lgan birinchi maska oktetini toping; **blok qadami** $s=256-m$, bu yerda $m$ niqobning chegara okteti. IPning shu oktetdagi $x$ qiymati uchun blok boshi $\\lfloor x/s\\rfloor s$, bloki oxiri $\\lfloor x/s\\rfloor s+s-1$. Qolgan host oktetlari networkda 0, broadcastda 255 bo'ladi.\n\n**Ishlangan misol: 1-misol. /27 subnet**\n\n`192.168.10.34/27`: maska `255.255.255.224`. Qadam $s=256-224=32$. Oxirgi oktet 34, demak $\\lfloor34/32\\rfloor=1$ va blok 32--63.\n\nNatija | Manzil\n\nTarmoq | `192.168.10.32`\n\nBroadcast | `192.168.10.63`\n\nBirinchi usable | `192.168.10.33`\n\nOxirgi usable | `192.168.10.62`\n\nJami / usable | $2^5=32$ / $30$\n\nTekshiruv: 34 ham 32--63 oralig'ida, 33--62 ichida; host sifatida yaroqli.\n\n**Ishlangan misol: 2-misol. /20 va uchinchi oktet**\n\n`172.20.37.146/20`. Maska `255.255.240.0`; uchinchi oktetda blok $256-240=16$. $37$ soni 32--47 oralig'ida.\n\nN | =`172.20.32.0`, | B | =`172.20.47.255`,\n\n\\text{birinchi} | =`172.20.32.1`, | \\text{oxirgi} | =`172.20.47.254`.\n\nHostlar soni $2^{12}-2=4094$.\n\n**Ishlangan misol: 3-misol. /23 ikki /24ni birlashtiradi**\n\n`10.3.7.200/23`: niqob `255.255.254.0`. Uchinchi oktetdagi qadam $2$. Blok 6--7, shuning uchun network `10.3.6.0`, broadcast `10.3.7.255`, usable $2^9-2=510$.\n\n## Bir subnetdami?\n\nIkkala IPv4 uchun ham *berilgan bir xil subnet maskasi* bilan network hisoblanadi. Networklar bir xil bo'lsa, odatda bir subnetga tegishli. Bitta adres tarmoqqa, boshqasi broadcastga teng bo'lsa, host sifatida qo'llanilishi alohida tekshiriladi.\n\n**Ishlangan misol: 4-misol. Ikki manzilni solishtirish**\n\n`192.168.5.62/26` ning networki `192.168.5.0`; `192.168.5.65/26` ning networki `192.168.5.64`. Demak ular bir /26 subnetda emas. Bir xil `/24` bilan qaralsa, ikkalasi bitta /24 blokda bo'ladi. Prefiksni e'tiborsiz qoldirish — katta xato.\n\n## Nazorat algoritmi\n\n- IPv4 va /$p$ ni ajrating, /$p$ ni maskaga o'tkazing.\n\n- Birinchi qisman maskali oktet va blok qadamini belgilang.\n\n- Network va broadcastni toping; agar /0--/30 bo'lsa, usable diapazonni ajrating.\n\n- Manzillar soni va host sonini alohida tekshiring; topilgan manzil berilgan subnetga kirishiga ishonch hosil qiling.\n\n*Manba: M11, 172--179-betlar IP-manzillash tushunchasi; hisoblash algoritmi — shu mavzuni chuqurlashtiruvchi metodik sintez.*\n\n**Xulosa:** Network = IP AND maska; broadcast = network va host bitlari 1. /27 da blok 32; /26 da 64; /20 da uchinchi oktet bo'yicha 16.\n\n*V2 manba: 2026 spetsifikatsiya, 11-sinf va qo‘shimcha Cambridge darsliklari; ekspert ko‘rigi kutilmoqda.*"},{"ch":7,"title":"Subnet loyihalash, VLSM va IPv6 asoslari","body":"# Subnet loyihalash, VLSM va IPv6 asoslari\n\n**Maqsad**\n\nBerilgan host talabiga mos minimal prefiksni tanlash, subnetlarni ajratish va IPv6 ni IPv4 dan farqlash.\n\n## Host talabi bo'yicha prefiks tanlash\n\n$H$ ta oddiy IPv4 host zarur bo'lsa, eng kichik $h$ butun sonni toping:\n\\[2^h-2\\ge H,\\qquad p=32-h.\\]\n\n**Ishlangan misol: 30 ta host**\n\n$H=30$: $2^5-2=30$, demak $h=5$, $p=27$. /28 faqat 14 hostga mos; /27 — eng kichik yetarli subnet.\n\n**Ishlangan misol: 50 ta host**\n\n$2^5-2=30<50$; $2^6-2=62\\ge50$. Demak /26, jami 64 manzil, odatiy usable 62.\n\n**Ishlangan misol: 200 ta host**\n\n$2^7-2=126<200$; $2^8-2=254\\ge200$. Demak /24 tanlanadi.\n\n## Bitta tarmoqni teng subnetlarga bo'lish\n\n`192.168.40.0/24` ni 4 ta teng subnetga ajratish kerak. To'rtta subnet uchun 2 ta qo'shimcha tarmoq biti: yangi prefiks /26. Ularning networklari `192.168.40.0`, `192.168.40.64`, `192.168.40.128`, `192.168.40.192`. Har biri 64 ta adres va 62 ta odatiy usable hostga ega. Agar talab 8 ta teng subnet bo'lsa, 3 bit olinadi: /27.\n\n## VLSM: turli hajmdagi subnetlar\n\n**Variable-Length Subnet Mask** bir bazaviy blokni turli prefiks uzunliklariga ajratadi. Qoida: kattaroq host talabidan boshlab ketma-ket, mos blok chegaralarida joylashtiring.\n\n**Ishlangan misol: /24 ni 60, 25 va 10 host uchun ajratish**\n\nAsosiy blok `192.168.70.0/24`.\n\n- 60 host uchun /26 (62 usable): `192.168.70.0/26`, 0--63.\n\n- 25 host uchun /27 (30 usable): `192.168.70.64/27`, 64--95.\n\n- 10 host uchun /28 (14 usable): `192.168.70.96/28`, 96--111.\n\nBir-birini qoplamaydi. Qolgan manzillar boshqa maqsadlar uchun ishlatilishi mumkin. 60/25/10 — talab qilinadigan *usable* hostlar soni, jami adreslar soni emas.\n\n## Supernet va marshrut agregatsiyasi\n\nBir-biriga tutash, to'g'ri chegarada joylashgan ikki /24 subnetni umumiy /23 bilan ifodalash mumkin: masalan `192.168.8.0/24` va `192.168.9.0/24` yig'ilib `192.168.8.0/23` ni beradi. `192.168.9.0/23` bu misolda tarmoq chegarasi emas. Marshrut agregatsiyasi jadvalni qisqartiradi, lekin ehtiyotsiz qo'llansa ortiqcha manzillar ham qamrab olinishi mumkin.\n\n## 29-dars: tarmoqni loyihalash va tashkil etishning besh bosqichi\n\n11-sinf darsligidagi loyiha ketma-ketligi quyidagicha. Har bosqich keyingisi uchun qaror qabul qilishga tayyorlaydi:\n\n- **Maqsad va talabni aniqlash**: foydalanuvchilar, qurilmalar, printer, server, internet va xavfsizlik ehtiyoji.\n\n- **Arxitekturani tanlash**: mijoz/server yoki P2P; markazlashgan fayllar bo'lsa server va administrator zarurligini baholash.\n\n- **Aloqa vositasini tanlash**: ishchi kompyuterlar uchun kabel, mobil qurilmalar uchun Wi-Fi yoki aralash yechim; qamrov va tarmoqli kenglik.\n\n- **Qurilmalarni tanlash**: switch, AP, router, server, NIC, kabel va ulagichlar soni hamda xarajatlar.\n\n- **Dizayn/sxema chizish**: tugunlar, ulanishlar, joylashuv, manzillash, qayta tiklash va xavfsizlik chegaralari.\n\nKeyingi **tashkil etish** jarayonida qurilmalar joylanadi, kabellar va ulagichlar tayyorlanadi, ulanishlar o'rnatiladi, har bir subnet uchun IP/niqob/gateway konfiguratsiyasi beriladi va ulanish hamda resursga kirish tekshiriladi.\n\n**Ishlangan misol: Darslikka yaqin ikki kompyuter xonasi vaziyati**\n\nA xonada 8 PC, B xonada 10 PC; o'qituvchilar mobil qurilmadan ulanadi, hujjatlar esa umumiy fayl-serverda. Mos loyiha: ikkita mahalliy switch, markaziy switch, fayl-server, AP va Internetga chiqish uchun router. PC uchun Ethernet, ko'chma qurilmalar uchun Wi-Fi. Xodimlarning yagona serverdan foydalanish talabi mijoz/server arxitekturasini asoslaydi.\n\n**Diqqat: Darslikdagi modellarning zamonaviy sharti**\n\nDarslikdagi ``hub kam kompyuterga arzon'' yoki ``routerning o'zi switchdan har doim samaraliroq'' qabilidagi taqqoslashlar kontekstli, universal tavsiya emas. Zamonaviy LANda kommutator va router vazifalari bir-birini almashtirmaydi. Loyihalashda port soni, gigabit tezlik, xavfsizlik, xizmat ko'rsatish va narx alohida baholanadi.\n\n*Manba: M11, 180--185-betlar, 29-dars; C8, maktab tarmog'ini loyihalash moduli, PDF 91--113-betlar.*\n\n## IPv6 ning asosiy g'oyasi\n\n**IPv6** — 128 bitli manzil; 16 bitli sakkizta geksadesimal guruh orqali ifodalanadi, masalan `2001:db8:0:0:0:0:0:1`. Ketma-ket nol guruhlar bir joyda `::` ko'rinishida qisqartirilishi mumkin: `2001:db8::1`. `::` bir manzilda eng ko'pi bilan bir marta keladi. IPv6da IPv4 dagidek broadcast yo'q; multicast va boshqa mexanizmlar ishlatiladi.\n\nMezon | IPv4 | IPv6\n\nUzunlik | 32 bit | 128 bit\n\nYozilish | 4 ta o'nlik oktet | 8 ta hex guruh (qisqartirish mumkin)\n\nLoopback | 127.0.0.1 | ::1\n\nBroadcast | Bor | IPv4 turidagi broadcast yo'q\n\n*Manba: M11, 172--179-betlar IPv4/IPv6 kirish mavzusi; VLSM, agregatsiya va /31--/32 farqi — zamonaviy texnik kengaytma.*\n\n**Xulosa:** Host talabidan $h$ topiladi, keyin $p=32-h$. VLSM katta subnetdan kichikka; IPv6 128 bit, broadcast mexanizmi IPv4dan farq qiladi.\n\n*V2 manba: 2026 spetsifikatsiya, 11-sinf va qo‘shimcha Cambridge darsliklari; ekspert ko‘rigi kutilmoqda.*"},{"ch":8,"title":"Internet, WWW va tarmoq xizmatlari","body":"# Internet, WWW va tarmoq xizmatlari\n\n**Maqsad**\n\nInternet va WWWni, URL/domen/DNS/DHCPni, asosiy ilova protokollarini farqlash.\n\n## Internet va WWW aynan bitta tushuncha emas\n\n**Internet** — o'zaro bog'langan IP tarmoqlari infratuzilmasi. **WWW** — HTTP(S) orqali murojaat qilinadigan, o'zaro havolalangan veb-resurslar tizimi; bu internetning xizmatlaridan biri. Elektron pochta, fayl uzatish, VoIP va internet orqali ko'plab boshqa xizmatlar WWWga teng emas.\n\n## Brauzer, veb-server, domen, qidiruv tizimi\n\nTushuncha | Asosiy vazifa\n\nVeb-brauzer | Veb sahifalar so'raydi, kodni qayta ishlaydi va ko'rsatadi (masalan, Firefox).\n\nVeb-server | HTTP(S) so'rovlariga javob beradigan dastur/xizmat.\n\nQidiruv tizimi | Veb-ma'lumotlarni indekslash va so'rovga mos natijalarni topish xizmati.\n\nURL | Resursga murojaat qilish manzili, masalan `https://example.org/docs?a=1`.\n\nDomen | Ierarxik nomlash tizimidagi nom; IP bilan bog'lanishi mumkin.\n\nDNS | Domen nomi va tegishli yozuvlarni topish xizmati.\n\n## Internet xizmatlarining amaliy toifalari\n\nInternet orqali veb-sahifalarni o'qish (WWW), elektron pochta, fayl uzatish, videokonferensiya, bulutli saqlash, masofaviy ta'lim va xabar almashish mumkin. Xizmat (masalan, elektron pochta) bilan uni ko'radigan dastur (brauzer yoki pochta klienti) bir xil tushuncha emas.\n**Provayder (ISP)** tarmoqqa chiqish xizmatini taqdim etadi; **modem/ONT** esa muayyan liniya bilan abonent qurilmasini bog'laydi. URL manzilining domeni IP manzilga teng emas; DNS nomni manzilga moslashda ishlatiladi.\n\n*Manba: M11, 186--195-betlar; M6, 77--98-betlar, internet, veb va elektron pochta.*\n\n## URLni qismlarga ajratish\n\n`https://example.org:443/dars/tarmoq?q=ip\\#javob` manzilida: `https` — sxema; `example.org` — xost; `443` — port; `/dars/tarmoq` — yo'l; `q=ip` — query parametr; `\\#javob` — fragment. URL ichida qidiruv parametrining mavjudligi uning Google qidiruvi ekanini bildirmaydi.\n\n## DNS va DHCP\n\n**DNS** domen nomiga mos IP yoki boshqa DNS yozuvini beradi; **DHCP** mijozga IP, maska, gateway va DNS serveri kabi konfiguratsiyani avtomatik taqdim etishi mumkin. **NAT** esa ichki/tashqi manzillar orasida moslashtirish orqali bir nechta xususiy IPga ega qurilmaning internetga chiqishiga yordam berishi mumkin. DNS manzilni avtomatik tayinlamaydi, DHCP veb sahifalarni qidirmaydi.\n\n**Ishlangan misol: DNS ishlamaganida nima bo'ladi?**\n\nKompyuter internetdagi ma'lum IPga paket yubora oladi, ammo domen bilan sayt ochilmaydi. Sabablardan biri — DNS nomni IPga o'tkaza olmayapti. Internet ulanishi hamisha butunlay uzilgan degan xulosa noto'g'ri.\n\n## Muhim xizmatlar va protokollar\n\nProtokol | Odatdagi port | Vazifa\n\nHTTP | TCP 80 | Shifrlanmagan veb trafik\n\nHTTPS | TCP 443 | TLS yordamida himoyalangan veb trafik\n\nDNS | UDP/TCP 53 | Domen nomini aniqlash\n\nDHCPv4 | UDP 67/68 | IPv4 konfiguratsiya taqsimlash\n\nSMTP | TCP 25/587 | Elektron xatni serverga uzatish\n\nIMAP | TCP 143/993 | Pochta qutisini serverda boshqarish\n\nPOP3 | TCP 110/995 | Elektron xatni olish protokoli\n\nSSH | TCP 22 | Himoyalangan masofaviy konsol\n\nPortlar *odatdagi* qiymatlar: xizmatlar boshqa portlarda ham sozlanishi mumkin. HTTPS foydalanish saytning barcha mazmuni ishonchli degani emas; u ayniqsa tranzitdagi aloqani himoyalashga xizmat qiladi.\n\n## Internetga chiqish yo'lini diagnostika qilish\n\nAgar Wi-Fi belgisi bor-u internet yo'q bo'lsa, navbatma-navbat: (1) lokal IP va maskani; (2) default gatewayga erishishni; (3) DNS ishlashini; (4) provayder aloqasini tekshiring. Lokal APga ulanish provayder interneti ishlayotganini kafolatlamaydi.\n\n*Manba: M6, 77--96-betlar (17--20-darslar); M11, 186--196-betlar (30--31-darslar); C5/C6/C11 internet bo'limlari.*\n\n**Xulosa:** Internet — infratuzilma; WWW — xizmat; brauzer — dastur; qidiruv tizimi — indekslaydigan xizmat; DNS — nomni aniqlash; DHCP — konfiguratsiya berish.\n\n*V2 manba: 2026 spetsifikatsiya, 11-sinf va qo‘shimcha Cambridge darsliklari; ekspert ko‘rigi kutilmoqda.*"},{"ch":9,"title":"Brauzer va qidiruv tizimlarida samarali izlash","body":"# Brauzer va qidiruv tizimlarida samarali izlash\n\n**Maqsad**\n\nKalit so'z va qidiruv operatorlarini maqsadga muvofiq tanlash; topilgan axborotning ishonchliligini baholash.\n\n## Qidiruvning to'rt bosqichi\n\n- Savolni aniqlashtiring: mavzu, vaqt, hudud, til va kerakli format.\n\n- Asosiy kalit so'zlarni tanlang, ko'p ma'noli so'zlarni ajrating.\n\n- Qidiruv operatorlari va filtrlarni qo'llang.\n\n- Natijaning muallifi, sanasi, dalili, domeni va maqsadini tekshiring; kerak bo'lsa so'rovni qayta tuzing.\n\n## Qidiruv operatorlari\n\nSo'rov namunasi | Qachon foydali?\n\n`\"kompyuter tarmog'i\"` | Aniq iborani topish.\n\n`router -do'kon` | Keraksiz so'zni chiqarib tashlashga urinish.\n\n`site:edu.uz informatika` | Domen ichidan qidirish.\n\n`filetype:pdf IP manzil` | PDF formatiga e'tibor qaratish.\n\n`TCP OR UDP` | Atamalardan kamida birini izlash.\n\n`192.168.1.0/24 maska` | Aniqlangan texnik kalitlar bilan so'rov.\n\nOperatorlarning ishlashi qidiruv tizimiga qarab farq qiladi, maxsus belgilar hamma tizimda bir xil talqin qilinmasligi mumkin. Mantiqiy *AND* so'zi bilan qidirish va uning dastur tomonidan qo'llab-quvvatlanishi haqida ko'r-ko'rona umumlashma qilmang.\n\n**Ishlangan misol: Rasmiy darslikni topish**\n\nMaqsad: 11-sinf kompyuter tarmoqlarining darslikdagi PDF mavzusi. Aniq mavzu + rasmiy domen + PDF formatini tanlang; birinchi natija reklama yoki reklamasizligidan qat'i nazar, manba muallifini tekshiring. Masalan, `site:edu.uz \"kompyuter tarmoqlari\" filetype:pdf` so'rovi yaxshi boshlang'ich nuqta bo'lishi mumkin.\n\n## Qidiruv, baholash va faktcheking\n\n**Crawler** vebdagi sahifalarni avtomatik ko'rib chiqishi, **indeks** qayta ishlangan mazmun haqida yozuv saqlashi, **ranking** natijalarni foydalanuvchi so'roviga qarab tartiblashi mumkin. Natijaning reytingi uning ilmiy to'g'riligiga mutlaq kafolat emas.\n\n**Birlamchi manba** — faktning boshlang'ich hujjati yoki bevosita ma'lumoti; **ikkilamchi manba** — uni sharhlaydigan, tahlil qiladigan material. Manbani baholashda muallif vakolati, nashr sanasi, dalilga havola, moliyaviy manfaat, uslub va boshqa mustaqil manbalar bilan moslikni solishtiring.\n\n**Diqqat: Qidiruvdan topish — tasdiqlash emas**\n\nQidiruv tizimi ko'rsatgan qisqa izoh, blog va ijtimoiy tarmoq posti rasmiy ma'lumotga avtomatik teng emas. IP maska kabi hisobli masalada manbaning o'zini tekshiring va natijani mustaqil qayta hisoblang.\n\n## Natijalarni jadval asosida baholash\n\nQidiruv natijasi | Belgisi | Tekshirish yo'li\n\nVazirlikning rasmiy PDF hujjati | Vakolatli birlamchi manba bo'lishi mumkin | Sana, nom, versiya, amaldagi holat\n\nTijoriy saytdagi maqola | Ikkilamchi sharh | Muallif va birlamchi hujjatga havola\n\nAnonim ijtimoiy post | Tasdiqlanmagan bayon | Rasmiy yoki mustaqil ikki manba bilan tekshirish\n\nQidiruvdagi **aniq ibora**, **site:**, **filetype:**, **minus so'z** kabi operatorlar ba'zi qidiruv tizimlarida ishlaydi; har bir tizimda aynan bir xil emas. *Rasmiy sayt* ham eskirgan hujjatni ko'rsatishi mumkin: nashr va amal sanasiga qarash zarur.\n\n*Manba: M6, 81--91-betlar, internetda axborot izlash; C5, qidirish mashqlari, PDF 1--139; C8, veb va internet.*\n\n## Raqamli iz va mualliflik huquqi\n\nMatn, rasm va fayllarni topish ularni istalgancha ko'chirishga ruxsat bermaydi. Foydalanish litsenziyasi, iqtibos miqdori, mualliflik ko'rsatish va maxfiy ma'lumotlar bilan ishlash qoidalariga rioya qiling. Bosilgan havola nomi haqiqiy manzil bilan mosligini tekshirish foydali.\n\n*Manba: M6, 81--91-betlar (qidiruv tizimlari); C5/C6 qidirish va ma'lumotni baholash; M11 internet mavzulari.*\n\n**Xulosa:** So'rovni operator bilan toraytiring, ammo topilgan har bir natijani manba, sana va dalil bo'yicha qayta baholang.\n\n*V2 manba: 2026 spetsifikatsiya, 11-sinf va qo‘shimcha Cambridge darsliklari; ekspert ko‘rigi kutilmoqda.*"},{"ch":10,"title":"Internetdan xavfsiz va maqsadli foydalanish","body":"# Internetdan xavfsiz va maqsadli foydalanish\n\n**Maqsad**\n\nTahdidlarni tanish, xavfsiz ulanish va hisobni himoyalash choralarini tanlash; amaliy vaziyatda eng to'g'ri harakatni belgilash.\n\n## Asosiy tahdidlar\n\n**Phishing** — foydalanuvchini aldab parol, kod yoki boshqa maxfiy ma'lumotini olishga qaratilgan urinish; **malware** — zararli dasturlar umumiy nomi; **ransomware** — ma'lumotni shifrlab yoki unga kirishni cheklab to'lov talab qiluvchi zararli dastur. **Spoofing** — manba yoki identifikatorni qalbakilashtirish; **social engineering** — insonni manipulyatsiya qilish orqali himoyani chetlab o'tish.\n\n## Xavfsiz foydalanishning ustuvor choralari\n\n- Har hisob uchun kuchli, noyob parol yoki passkey tanlash; imkon bo'lsa MFA yoqish.\n\n- Operatsion tizim, brauzer va tarmoq qurilmasi dasturiy ta'minotini muntazam yangilash.\n\n- E-mail va messenjerlardan kelgan kutilmagan fayl yoki havolani ochishdan oldin manbani mustaqil tekshirish.\n\n- Qurilma, akkaunt va bulut resurslarining ruxsatlarini ehtiyojga ko'ra cheklash.\n\n- Muhim ma'lumotlarni alohida joyga zaxiralash va qayta tiklashni sinab ko'rish.\n\n## HTTP, HTTPS, TLS va sertifikat\n\nHTTPS odatda TLS bilan shifrlangan HTTP aloqasini ta'minlaydi; brauzer server sertifikatini tekshiradi. Qulf belgisi ma'lumotning uzatish chog'ida himoyalanganligini anglatishi mumkin, ammo saytning mazmuni to'g'ri yoki savdogar halol ekanini isbotlamaydi.\n\n## Ochiq Wi-Fi va router sozlash\n\nOchiq jamoat Wi-Fi tarmog'ida shaxsiy xizmatlarga kirganda domen va HTTPSni tekshiring, tizim yangilangan bo'lsin; avtomatik ulanishni cheklang. Uy Wi-Fi tarmog'ida WPA2-AES yoki WPA3, kuchli parol, o'zgartirilgan administrator paroli va muntazam firmware yangilash muhim. **WEP** eskirgan va xavfsiz emas.\n\n## Maxfiylik va raqamli madaniyat\n\n**Shaxsiy ma'lumot** hamda identifikatorlarni keragidan ortiq oshkor qilmaslik, sahifa ruxsatlari va cookie sozlamalarini tushunish zarur. Internetdan maqsadli foydalanish qidiruv natijalarini dalil bilan solishtirish, ishonchli manba tanlash va boshqalarning intellektual huquqlarini hurmat qilishni ham o'z ichiga oladi.\n\n**Ishlangan misol: Vaziyatli baholash**\n\nElektron pochta ``Hisobingiz bloklanadi, darhol shu havolaga kiring'' deb tahdid qilmoqda. Xabar ichidagi linkni bosish o'rniga xizmatning rasmiy manzilini mustaqil ochish yoki rasmiy ilovadan tekshirish xavfsizroq. SMSdagi kodni uchinchi shaxsga aytmang.\n\n## Ochiq tarmoqda tahdidni ajratish va javob chorasi\n\nHodisa | Xavf | To'g'ri birinchi choralar\n\nShubhali SMS/parol so'rovi | Phishing, hisob egallanishi | Mustaqil rasmiy kanal; kodni bermaslik; MFA\n\nBegona Wi-Fi SSID | Soxta kirish nuqtasi | Tarmoq egasidan aniqlash; himoyalangan sayt/VPN ehtiyoji\n\nBrauzer sertifikat xatosi | Soxta server yoki noto'g'ri sozlama | Ogohlantirishni chetlab o'tmasdan tekshirish\n\nZararli fayl | Malware yoki ransomware | Ochmaslik; yangilash; ishonchli skan va zaxira\n\nInternetdan **maqsadli foydalanish** faqat xakerlikdan himoyalanish emas: izlash vazifasini aniq belgilash, shaxsiy ma'lumotni oshkor qilmaslik, axborot manbasini baholash, litsenziyaga rioya qilish va vaqtni oqilona boshqarish ham kiradi.\n\n*Manba: M11, 256--310-betlar, xavfsizlik boblari; C11, xavfsizlik va internet mavzulari.*\n\n## DNS, DHCP va NAT xavfsizlik emas\n\nDNS — nomlash, DHCP — konfiguratsiya, NAT — manzil moslashtirish mexanizmi. Ular o'z-o'zidan hujumlardan to'laqonli himoya qilmaydi; firewall, yangilanish, kirish nazorati va himoyalangan protokollar bilan birga ishlatiladi.\n\n*Manba: M11, 256--310-betlar (axborot, kompyuter va tarmoq xavfsizligi); C11 xavfsizlik bo'limlari; 2026 spetsifikatsiyasidagi 6-bo'limning xavfsiz internet talabi.*\n\n**Xulosa:** HTTPS aloqa xavfsizligini oshiradi, lekin sahifa haqqoniyligining kafolati emas. Phishingda rasmiy kanal bilan mustaqil tekshirish — ustuvor.\n\n\\appendix\n\n*V2 manba: 2026 spetsifikatsiya, 11-sinf va qo‘shimcha Cambridge darsliklari; ekspert ko‘rigi kutilmoqda.*"}]$theory$::jsonb) LOOP
    lid := md5('task220-m12-v2-lesson-' || (x->>'ch'))::uuid;
    INSERT INTO public.lessons
      (id,module_id,order_idx,slug,title_uz,body_mdx,est_minutes,status,topic_test_question_count)
    VALUES
      (lid,v_module,10+(x->>'ch')::integer,'tarmoq-v2-bob-'||lpad(x->>'ch',2,'0'),
       x->>'title',x->>'body',30,'draft'::public.content_status,30)
    ON CONFLICT (id) DO NOTHING;
    IF NOT EXISTS(SELECT 1 FROM public.lessons
       WHERE id=lid AND module_id=v_module AND status='draft'::public.content_status)
    THEN RAISE EXCEPTION 'TASK220 lesson identity/status collision for chapter %',x->>'ch'; END IF;
  END LOOP;
  FOR q IN SELECT value FROM jsonb_array_elements($items$[{"id":"TAR-01-001","ch":1,"fmt":"Y1","lev":"A","stem":"Kompyuter tarmog'ining asosiy vazifasi qaysi?","options":["Resurs almashish va aloqa","Faqat operatsion tizim o'rnatish","Faqat ekran o'lchamini kattalashtirish","Faqat matnni formatlash"],"answer":"A","explanation":"Tarmoq qurilmalar va xizmatlarning o'zaro axborot almashuviga xizmat qiladi.","source":"M11, 129--139-betlar; C8, PDF 91--96","code":"S6.NET.01","visual":""},{"id":"TAR-01-002","ch":1,"fmt":"Y1","lev":"D","stem":"Tashkilot xodimlari login bilan ichki hujjat portaliga kiradi; ommaviy foydalanuvchi kira olmaydi. Bu nima?","options":["Internetning hammaga ochiq veb-qidiruvi","Intranet","Wi-Fi qurilmasining MAC manzili","WANdagi avtomatik marshrut jadvali"],"answer":"B","explanation":"Intranet ichki ruxsatli auditoriyaga mo'ljallangan.","source":"M11, 136--138-betlar","code":"S6.NET.01","visual":""},{"id":"TAR-01-003","ch":1,"fmt":"Y1","lev":"A","stem":"Tarmoq tuguni (node) nima?","options":["Faqat internet provayderi","Faqat bosh server","Tarmoqqa ulangan element","Faqat optik kabel"],"answer":"C","explanation":"Tugun deganda tarmoqdagi qurilma yoki manzillanadigan element tushuniladi.","source":"M11, 129--139-betlar; C8, PDF 91--96","code":"S6.NET.01","visual":""},{"id":"TAR-01-004","ch":1,"fmt":"Y1","lev":"D","stem":"Maktab tashqi yetkazib beruvchiga faqat buyurtma sahifasini ochdi, ichki kadrlar bazasini emas. Bu qanday kirish?","options":["Ichki bazani Internetda hammaga ochish","Lokal interfeysni tarmoqdan uzish","Faqat printer drayverini yangilash","Extranetga xos cheklangan hamkor kirishi"],"answer":"D","explanation":"Tashqi hamkor uchun nazoratli ruxsat extranet g'oyasiga mos.","source":"M11, 136--138-betlar; kengaytirma","code":"S6.NET.01","visual":""},{"id":"TAR-01-005","ch":1,"fmt":"Y1","lev":"A","stem":"Server tushunchasining asosiy belgisi nima?","options":["Xizmat ko'rsatuvchi tizim","Har qanday qidiruv so'zi","Faqat tarmoq kabeli","Yagona simsiz antenna"],"answer":"A","explanation":"Server mijozlarga tarmoq orqali xizmat beradi.","source":"M11, 129--139-betlar; C8, PDF 91--96","code":"S6.NET.01","visual":""},{"id":"TAR-01-006","ch":1,"fmt":"Y1","lev":"D","stem":"Quyidagi jadvalda filiallar A va B ikki shaharda, har bir filial ichidagi qurilmalar bitta xonada. Qaysi tuzilish mos?","options":["Har ikkala filial bitta fizik WLAN bo'lishi shart","Har bir filial LAN, ularni bog'lovchi aloqa WAN","Har bir kompyuter mustaqil Internet provayderi","Har bir filial faqat PAN, filiallar orasida Bluetooth"],"answer":"B","explanation":"Mahalliy segment va uzoq masofali bog'lanish turli qamrovdir.","source":"M11, 129--136-betlar","code":"S6.NET.01","visual":"table_area"},{"id":"TAR-01-007","ch":1,"fmt":"Y1","lev":"A","stem":"Xost (host) odatda nimani anglatadi?","options":["Faqat signal kuchaytirgich","Faqat kabel ulagichi","Manzillanadigan yakuniy qurilma","Faqat optik tola"],"answer":"C","explanation":"Xost tarmoqda muloqot qiladigan manzillanadigan qurilmadir.","source":"M11, 129--139-betlar; C8, PDF 91--96","code":"S6.NET.01","visual":""},{"id":"TAR-01-008","ch":1,"fmt":"Y1","lev":"D","stem":"Uy routeriga ulangan noutbuk va printer provayder tarmog'i uzilganda ham o'zaro ishladi. Qaysi hukm asosli?","options":["Wi-Fi belgisi provayderni majburiy qayta ulaydi","Printer faqat tashqi DNS orqali ishlaydi","MAC manzillar Internet uzilganda yo'qoladi","Lokal LAN ishlashi uchun doim Internet talab qilinmaydi"],"answer":"D","explanation":"Mahalliy kadrlar uzatilishi Internet ulanishiga mustaqil bo'lishi mumkin.","source":"M11, 129--139-betlar","code":"S6.NET.01","visual":""},{"id":"TAR-01-009","ch":1,"fmt":"Y1","lev":"A","stem":"PAN qaysi turdagi tarmoq?","options":["Shaxsiy yaqin masofali tarmoq","Mahalliy magistral shina","Qit'alararo WAN","Shahar miqyosidagi MAN"],"answer":"A","explanation":"PAN shaxsga yaqin qurilmalarni bog'laydi.","source":"M11, 129--139-betlar; C8, PDF 91--96","code":"S6.NET.01","visual":""},{"id":"TAR-01-010","ch":1,"fmt":"Y1","lev":"C","stem":"Maktabdagi telefon Bluetooth bilan quloqchinga, Wi-Fi bilan mahalliy kirish nuqtasiga ulangan. Bitta telefonda qaysi ikkita aloqa mavjud?","options":["Faqat MAN va WAN","PAN va WLAN","Faqat kabel LAN va modem","Faqat ikkita WAN"],"answer":"B","explanation":"Bluetooth yaqin shaxsiy, Wi-Fi lokal simsiz tarmoq.","source":"M11, 129--135-betlar","code":"S6.NET.01","visual":""},{"id":"TAR-01-011","ch":1,"fmt":"Y1","lev":"A","stem":"LAN nimani bildiradi?","options":["Faqat mobil aloqa","Birgalikdagi internet domeni","Mahalliy tarmoq","Butunjahon qidiruv tizimi"],"answer":"C","explanation":"LAN mahalliy hududdagi qurilmalarni birlashtiradi.","source":"M11, 129--139-betlar; C8, PDF 91--96","code":"S6.NET.01","visual":""},{"id":"TAR-01-012","ch":1,"fmt":"Y1","lev":"D","stem":"Bitta informatika xonasidagi 20 PC bir switchga ulangan. Bu qanday tarmoq?","options":["Faqat mobil aloqa","Butunjahon qidiruv tizimi","Faqat ekran o'lchamini kattalashtirish","Mahalliy tarmoq"],"answer":"D","explanation":"LAN mahalliy hududdagi qurilmalarni birlashtiradi.","source":"M11, 129--139-betlar; C8, PDF 91--96","code":"S6.NET.01","visual":""},{"id":"TAR-01-013","ch":1,"fmt":"Y1","lev":"A","stem":"WLAN nima?","options":["Simsiz lokal tarmoq","Har doim global WAN","Optik ulanish protokoli","SMTP server"],"answer":"A","explanation":"WLAN — radioaloqa asosidagi mahalliy LAN.","source":"M11, 129--139-betlar; C8, PDF 91--96","code":"S6.NET.01","visual":""},{"id":"TAR-01-014","ch":1,"fmt":"Y1","lev":"D","stem":"Kichik ofis kompyuterlari bir xil Wi-Fi nuqtasiga bog'langan. Qaysi tur?","options":["Har doim global WAN","Simsiz lokal tarmoq","Faqat ekran o'lchamini kattalashtirish","Optik ulanish protokoli"],"answer":"B","explanation":"WLAN — radioaloqa asosidagi mahalliy LAN.","source":"M11, 129--139-betlar; C8, PDF 91--96","code":"S6.NET.01","visual":""},{"id":"TAR-01-015","ch":1,"fmt":"Y1","lev":"B","stem":"MAN tipik qaysi hududni qamraydi?",