mask = 172.25.14.0; blokdagi oxirgi adres 172.25.14.255.","source":"M11, 172--179-betlar; matematik/metodik chuqurlashtirish","code":"S6.NET.03","visual":""},{"id":"TAR-06-026","ch":6,"fmt":"Y1","lev":"E","stem":"192.168.7.222/29 oddiy IPv4 subnetida oxirgi foydalaniladigan host manzili qaysi?","options":["192.168.7.221","192.168.7.216","192.168.7.222","192.168.7.223"],"answer":"C","explanation":"Broadcast 192.168.7.223; undan bir oldin oxirgi host 192.168.7.222.","source":"M11, 172--179-betlar; matematik/metodik chuqurlashtirish","code":"S6.NET.03","visual":"ipline"},{"id":"TAR-06-027","ch":6,"fmt":"Y1","lev":"D","stem":"192.168.16.73/26 IP manzilining tarmoq (network) manzilini hisoblang.","options":["192.168.16.63","192.168.16.65","192.168.16.66","192.168.16.64"],"answer":"D","explanation":"192.168.16.73/26 uchun IP AND mask = 192.168.16.64; blokdagi oxirgi adres 192.168.16.127.","source":"M11, 172--179-betlar; matematik/metodik chuqurlashtirish","code":"S6.NET.03","visual":""},{"id":"TAR-06-028","ch":6,"fmt":"Y1","lev":"E","stem":"192.168.16.73/26 subnetining broadcast manzilini toping.","options":["192.168.16.127","192.168.16.125","192.168.16.126","192.168.16.128"],"answer":"A","explanation":"Tarmoq 192.168.16.64, barcha host bitlari 1 bo‘lganda broadcast 192.168.16.127.","source":"M11, 172--179-betlar; matematik/metodik chuqurlashtirish","code":"S6.NET.03","visual":""},{"id":"TAR-06-029","ch":6,"fmt":"Y1","lev":"D","stem":"10.11.35.204/19 IP manzilining tarmoq (network) manzilini hisoblang.","options":["10.11.31.255","10.11.32.0","10.11.32.2","10.11.32.1"],"answer":"B","explanation":"10.11.35.204/19 uchun IP AND mask = 10.11.32.0; blokdagi oxirgi adres 10.11.63.255.","source":"M11, 172--179-betlar; matematik/metodik chuqurlashtirish","code":"S6.NET.03","visual":""},{"id":"TAR-06-030","ch":6,"fmt":"Y1","lev":"E","stem":"10.11.35.204/19 oddiy subnetida nechta usable IPv4 host mavjud?","options":["8192","8191","8190","4094"],"answer":"C","explanation":"Prefiks /19: 8192 jami adres, network va broadcastdan tashqari 8190 usable host.","source":"M11, 172--179-betlar; matematik/metodik chuqurlashtirish","code":"S6.NET.03","visual":""},{"id":"TAR-07-003","ch":7,"fmt":"Y1","lev":"A","stem":"5 ta oddiy usable host joylashtirish uchun eng kichik yetarli IPv4 subnet prefiksi qaysi?","options":["/29","/30","/28","/31"],"answer":"A","explanation":"2^3-2=6 ta usable manzil /29 da mavjud; undan kichik blok yetmaydi.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03","visual":""},{"id":"TAR-07-004","ch":7,"fmt":"Y1","lev":"B","stem":"11-sinf 29-darsdagi tarmoq loyihalashning birinchi bosqichi nima?","options":["Avval barcha kabellarni kesib qo'yish","Maqsad va ehtiyojlarni aniqlash","Tarmoqni baholamay shunchaki ulash","Faqat IPni tasodifiy taqsimlash"],"answer":"B","explanation":"Darslik avval tarmoq vazifasi va hajmini aniqlashni talab qiladi.","source":"M11, 180-bet, 29-dars","code":"S6.NET.03","visual":""},{"id":"TAR-07-005","ch":7,"fmt":"Y1","lev":"A","stem":"14 ta oddiy usable host joylashtirish uchun eng kichik yetarli IPv4 subnet prefiksi qaysi?","options":["/30","/29","/28","/27"],"answer":"C","explanation":"2^4-2=14 ta usable manzil /28 da mavjud; undan kichik blok yetmaydi.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03","visual":""},{"id":"TAR-07-006","ch":7,"fmt":"Y1","lev":"E","stem":"Maktabda umumiy fayl-server, ikkita kompyuter xonasi va o'qituvchilar noutbuklari bor. Qaysi loyiha mos?","options":["Serverni o'chirib, barcha hujjatni bitta USBda saqlash","Barcha qurilmaga bitta koaksial kabelni ketma-ket ulash","Faqat quloqchin uchun Bluetooth PAN","Mijoz/server; xonalarga switch, mobil uchun AP, tashqi chiqish uchun router"],"answer":"D","explanation":"Darslikning 182--184-betlardagi vaziyati markazlashgan resurs va aralash aloqani ko'rsatadi.","source":"M11, 182--184-betlar","code":"S6.NET.03","visual":"design"},{"id":"TAR-07-007","ch":7,"fmt":"Y1","lev":"C","stem":"30 ta oddiy usable host joylashtirish uchun eng kichik yetarli IPv4 subnet prefiksi qaysi?","options":["/27","/28","1-c, 2-a, 3-b","/26"],"answer":"A","explanation":"2^5-2=30 ta usable manzil /27 da mavjud; undan kichik blok yetmaydi.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03","visual":""},{"id":"TAR-07-008","ch":7,"fmt":"Y1","lev":"D","stem":"24 ta PC, bitta umumiy printer va Internet talab etilgan. Xarid ro'yxatida 8 portli switch yakka o'zi yetadimi?","options":["Yo'q; chunki printer hech qachon LANda ishlamaydi","Yo'q; kompyuterlar va boshqa interfeyslar uchun portlar soni yetmaydi","Ha; portlar soni hech qachon ahamiyatli emas","Ha; 8 portga 24 PC bir vaqtda kabelsiz ulanadi"],"answer":"B","explanation":"Portlar soni va uplinklarni hisoblash zarur.","source":"M11, 180--185-betlar","code":"S6.NET.03","visual":""},{"id":"TAR-07-009","ch":7,"fmt":"Y1","lev":"C","stem":"45 ta oddiy usable host joylashtirish uchun eng kichik yetarli IPv4 subnet prefiksi qaysi?","options":["/27","/28","/26","/25"],"answer":"C","explanation":"2^6-2=62 ta usable manzil /26 da mavjud; undan kichik blok yetmaydi.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03","visual":""},{"id":"TAR-07-010","ch":7,"fmt":"Y1","lev":"D","stem":"Tarmoq qurilmalarini joylashtirgandan keyin IP manzil rejasi tuzildi. Qaysi tekshiruv ustuvor?","options":["Hamma qurilmaga bitta IP berish","Kabel turidan qat'i nazar DNSni o'chirish","Faqat fon rasmi bir xil bo'lishi","Subnetlar qoplanmasligi, gateway va manzillar noyobligi"],"answer":"D","explanation":"Manzillash xatolari qurilmalar ishlashiga to'sqinlik qiladi.","source":"M11, 183--184-betlar; hisoblash sintezi","code":"S6.NET.03","visual":""},{"id":"TAR-07-011","ch":7,"fmt":"Y1","lev":"D","stem":"62 ta oddiy usable host joylashtirish uchun eng kichik yetarli IPv4 subnet prefiksi qaysi?","options":["/26","1-a, 2-c, 3-b","/25","/27"],"answer":"A","explanation":"2^6-2=62 ta usable manzil /26 da mavjud; undan kichik blok yetmaydi.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03","visual":""},{"id":"TAR-07-012","ch":7,"fmt":"Y1","lev":"E","stem":"60 va 25 hostli ikki subnetni 192.168.70.0/24 ichida qoplamasdan ajratish uchun eng kichik prefikslar?","options":["/27 va /28","/26 va /27","/28 va /28","/25 va /29"],"answer":"B","explanation":"60 host uchun 62 usable (/26), 25 uchun 30 usable (/27).","source":"M11, 172--185-betlar; VLSM kengaytirma","code":"S6.NET.03","visual":""},{"id":"TAR-07-013","ch":7,"fmt":"Y1","lev":"E","stem":"192.168.16.0/24 blokini 4 ta teng subnetga bo'lishda yangi prefiks nima?","options":["/25","1-c, 2-a, 3-b","/26","/27"],"answer":"C","explanation":"4=2^2; tarmoqdan 2 qo'shimcha bit olinadi: /24+2=/26.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03","visual":"design"},{"id":"TAR-07-014","ch":7,"fmt":"Y1","lev":"B","stem":"192.168.50.0/24 bazaviy blokini 4 ta bir xil hajmdagi subnetga bo‘lish uchun yangi prefiks qaysi?","options":["/25","/27","1-b, 2-a, 3-c","/26"],"answer":"D","explanation":"4=2^2 yangi tarmoq biti olinadi: /24+2=/26.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03","visual":""},{"id":"TAR-07-015","ch":7,"fmt":"Y1","lev":"E","stem":"192.168.88.0/24 blokini 8 ta teng subnetga bo'lishda yangi prefiks nima?","options":["/27","/28","/26","/24"],"answer":"A","explanation":"8=2^3; tarmoqdan 3 qo'shimcha bit olinadi: /24+3=/27.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03","visual":"ipline"},{"id":"TAR-07-016","ch":7,"fmt":"Y1","lev":"B","stem":"10.4.0.0/24 bazaviy blokini 16 ta bir xil hajmdagi subnetga bo‘lish uchun yangi prefiks qaysi?","options":["/29","/28","/27","1-a, 2-c, 3-b"],"answer":"B","explanation":"16=2^4 yangi tarmoq biti olinadi: /24+4=/28.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03","visual":""},{"id":"TAR-07-017","ch":7,"fmt":"Y1","lev":"E","stem":"10.16.0.0/23 blokini 4 ta teng subnetga bo'lishda yangi prefiks nima?","options":["/24","/23","/25","/26"],"answer":"C","explanation":"4=2^2; tarmoqdan 2 qo'shimcha bit olinadi: /23+2=/25.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03","visual":"design"},{"id":"TAR-07-018","ch":7,"fmt":"Y1","lev":"D","stem":"10.25.0.0/23 bazaviy blokini 4 ta bir xil hajmdagi subnetga bo‘lish uchun yangi prefiks qaysi?","options":["/24","1-a, 2-c, 3-b","/26","/25"],"answer":"D","explanation":"4=2^2 yangi tarmoq biti olinadi: /23+2=/25.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03","visual":""},{"id":"TAR-07-019","ch":7,"fmt":"Y1","lev":"E","stem":"172.20.0.0/22 blokini 8 ta teng subnetga bo'lishda yangi prefiks nima?","options":["/25","/24","/22","/26"],"answer":"A","explanation":"8=2^3; tarmoqdan 3 qo'shimcha bit olinadi: /22+3=/25.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03","visual":"ipline"},{"id":"TAR-07-020","ch":7,"fmt":"Y1","lev":"E","stem":"192.168.20.0/24 bazaviy blokini 4 ta bir xil hajmdagi subnetga bo‘lish uchun yangi prefiks qaysi?","options":["/25","/26","1-2-3","/27"],"answer":"B","explanation":"4=2^2 yangi tarmoq biti olinadi: /24+2=/26.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03","visual":""},{"id":"TAR-07-021","ch":7,"fmt":"Y1","lev":"E","stem":"10.100.64.0/20 bazaviy blokini 16 ta bir xil hajmdagi subnetga bo‘lish uchun yangi prefiks qaysi?","options":["1-a, 2-c, 3-b","/23","/24","/25"],"answer":"C","explanation":"16=2^4 yangi tarmoq biti olinadi: /20+4=/24.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03","visual":""},{"id":"TAR-07-022","ch":7,"fmt":"Y1","lev":"B","stem":"IPv6 manzil uzunligi necha bit?","options":["32 bit","64 bit","48 bit","128 bit"],"answer":"D","explanation":"IPv6 128 bitli manzil tizimidir.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03","visual":""},{"id":"TAR-07-023","ch":7,"fmt":"Y1","lev":"B","stem":"IPv6ning ikki nuqta bilan ajratilgan to‘liq yozilishida nechta 16 bitli guruh bo‘ladi?","options":["8 ta","6 ta","16 ta","4 ta"],"answer":"A","explanation":"128/16=8 ta guruh.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03","visual":""},{"id":"TAR-07-024","ch":7,"fmt":"Y1","lev":"C","stem":"IPv6 loopback manzili qaysi?","options":["2001:db8::1","::1","::ffff:1","127.0.0.1"],"answer":"B","explanation":"IPv6da ::1 loopback.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03","visual":""},{"id":"TAR-07-025","ch":7,"fmt":"Y1","lev":"C","stem":"IPv6da IPv4ga xos broadcast mavjudmi?","options":["Ha, har bir /64da maxsus broadcast bor","Ha, ::1 broadcast","Yo‘q, IPv6 multicast va boshqa mexanizmlardan foydalanadi","Ha, 255.255.255.255 ishlatiladi"],"answer":"C","explanation":"IPv6da IPv4 broadcast modeli ishlatilmaydi.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03","visual":""},{"id":"TAR-07-026","ch":7,"fmt":"Y1","lev":"C","stem":"IPv6 manzilida :: qisqartmasi qanday vazifani bajaradi?","options":["Har qanday o‘nlik guruhni almashtiradi","TCP segmentini bildiradi","Manzil oxiridagi portni bildiradi","Ketma-ket nol guruhlarni ifodalaydi"],"answer":"D","explanation":":: ketma-ket nol guruhlarni bitta joyda qisqartiradi.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03","visual":""},{"id":"TAR-07-027","ch":7,"fmt":"Y1","lev":"C","stem":"IPv6da :: yozuvi bir manzilda necha marta kelishi mumkin?","options":["Eng ko‘pi bilan bir marta","Istalgancha marta","Aynan ikki marta","Kamida uch marta"],"answer":"A","explanation":"Aks holda tashlab ketilgan guruhlarning uzunligini tiklab bo‘lmaydi.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03","visual":""},{"id":"TAR-07-028","ch":7,"fmt":"Y1","lev":"E","stem":"VLSM loyihalashda subnetlarni qanday tartibda joylashtirish qulay?","options":["Tasodifiy har qanday blokdan","Katta host talabidan kichigiga","Faqat alifbo tartibida","Har doim kichikdan kattaga"],"answer":"B","explanation":"Katta bloklarni birinchi tanlash fragmentatsiya va ustma-ustlikni kamaytiradi.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03","visual":""},{"id":"TAR-07-029","ch":7,"fmt":"Y1","lev":"E","stem":"192.168.8.0/24 va 192.168.9.0/24 ni birlashtiruvchi to‘g‘ri /23 tarmoq qaysi?","options":["192.168.10.0/23","192.168.7.0/23","192.168.8.0/23","192.168.9.0/23"],"answer":"C","explanation":"/23 da uchinchi oktet ikki qadamli blok: 8-9.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03","visual":""},{"id":"TAR-07-030","ch":7,"fmt":"Y1","lev":"E","stem":"VLSMda ikkita subnetni bir-birining ustiga tushirmaslik uchun nima tekshiriladi?","options":["Faqat Wi-Fi paroli","Faqat DNS domeni","Faqat kompyuter nomlari","Blok chegaralari va manzil diapazonlari"],"answer":"D","explanation":"Subnet diapazonlari o‘zaro kesishmasligi kerak.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03","visual":""}]$items$::jsonb) LOOP
    SELECT id INTO STRICT c FROM public.constructs WHERE code=q->>'code' AND group_code='S6.NET';
    qid := md5('task220-m12-v2-question-'||(q->>'id'))::uuid;
    lid := md5('task220-m12-v2-lesson-'||(q->>'ch'))::uuid;
    source := 'network-v2-20261018:'||(q->>'id')||':original-'||(q->>'fmt');
    INSERT INTO public.lesson_constructs(lesson_id,construct_id,is_required,is_critical,min_questions)
    VALUES(lid,c,true,false,1)
    ON CONFLICT(lesson_id,construct_id) DO NOTHING;
    visual_md := CASE q->>'visual'
      WHEN 'table_area' THEN E'\n\n| Filial | Qurilmalar | Joylashuv |\n|---|---|---|\n| A | 10 PC va printer | 1-shahar |\n| B | 8 PC va printer | 2-shahar |'
      WHEN 'diagram_sw' THEN E'\n\nPC-A — Switch — PC-B'
      WHEN 'diagram_route' THEN E'\n\nLAN-A — Router — LAN-B'
      WHEN 'topo_star' THEN E'\n\n     PC-A\n       |\nPC-B — Switch — PC-C\n       |\n     PC-D'
      WHEN 'topo_ring' THEN E'\n\nA — B — C — D — A (halqa)'
      WHEN 'ipline' THEN E'\n\nIP AND subnet maskasi = tarmoq manzili'
      WHEN 'design' THEN E'\n\nTalab → loyiha → uskunalar → sozlash → sinash'
      ELSE '' END;
    INSERT INTO public.questions
      (id,subject_id,construct_id,group_code,format,cognitive,difficulty,
       stem_md,assets,status,source_reference,source_lesson_id)
    VALUES
      (qid,v_subject,c,'S6.NET','Y1'::public.question_format,
       (CASE WHEN q->>'lev' IN ('A','B') THEN 'bilish'
             WHEN q->>'lev' IN ('C','D') THEN 'qollash'
             ELSE 'mulohaza' END)::public.cognitive_level,
       (CASE q->>'lev' WHEN 'A' THEN 1 WHEN 'B' THEN 2 WHEN 'C' THEN 3 WHEN 'D' THEN 4 ELSE 5 END),
       (CASE WHEN q->>'fmt'<>'Y1' THEN
          (CASE q->>'fmt' WHEN 'Y2' THEN '**Moslashtirish: to‘g‘ri kombinatsiyani tanlang.**'
                            ELSE '**Ketma-ketlik: to‘g‘ri kombinatsiyani tanlang.**' END) || E'\n\n'
        ELSE '' END) || (q->>'stem') || visual_md,
       '[]'::jsonb,'review'::public.content_status,source,lid)
    ON CONFLICT(id) DO NOTHING;
    IF NOT EXISTS(SELECT 1 FROM public.questions
         WHERE id=qid AND source_reference=source AND status='review'::public.content_status)
    THEN RAISE EXCEPTION 'TASK220 question identity/status collision %',q->>'id'; END IF;
    chosen := NULL;
    FOR k IN 0..3 LOOP
      oid := md5('task220-m12-v2-option-'||(q->>'id')||'-'||k)::uuid;
      INSERT INTO public.question_options(id,question_id,side,order_idx,content_md)
      VALUES(oid,qid,'a',k+1,q->'options'->>k)
      ON CONFLICT(id) DO NOTHING;
      IF k = ascii(q->>'answer')-ascii('A') THEN chosen := oid; END IF;
    END LOOP;
    IF chosen IS NULL THEN RAISE EXCEPTION 'TASK220 answer key missing %',q->>'id'; END IF;
    INSERT INTO public.question_keys(question_id,payload,explanation_md)
    VALUES(qid,jsonb_build_object('correct_option_id',chosen),
           (q->>'explanation')||E'\n\nManba: '||(q->>'source')||
           E'\nDastlabki savol turi: '||(q->>'fmt'))
    ON CONFLICT(question_id) DO NOTHING;
  END LOOP;
  SELECT count(*) INTO actual_count FROM public.questions
    WHERE source_reference LIKE 'network-v2-20261018:%';
  IF actual_count<>300 THEN RAISE EXCEPTION 'TASK220 expected 300 review questions, got %',actual_count; END IF;
  SELECT count(*) INTO actual_count FROM public.lessons
    WHERE module_id=v_module AND slug LIKE 'tarmoq-v2-bob-%';
  IF actual_count<>10 THEN RAISE EXCEPTION 'TASK220 expected 10 theory chapters, got %',actual_count; END IF;
END $task220$;
COMMIT;
